class BlogService {
  private posts: BlogPost[] = [];

  constructor() {
    this.loadPosts();
  }

  private loadPosts(): void {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          this.posts = JSON.parse(stored);
          return;
        }
      }
      this.posts = [...DEFAULT_POSTS];
      this.saveToStorage();
    } catch (e) {
      this.posts = [...DEFAULT_POSTS];
    }
  }

  private saveToStorage(): void {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(this.posts));
      }
    } catch (e) {
      console.error('Error saving blog posts to localStorage', e);
    }
  }

  public getAllPosts(): BlogPost[] {
    this.loadPosts();
    return [...this.posts];
  }

  public getPublishedPosts(): BlogPost[] {
    this.loadPosts();
    return this.posts.filter(p => p.status === 'published');
  }

  public getPostsByCategory(category: 'guide' | 'news_trend'): BlogPost[] {
    this.loadPosts();
    return this.posts.filter(p => {
      if (category === 'guide') {
        return p.status === 'published' && (!p.category || p.category === 'guide');
      }
      return p.status === 'published' && p.category === 'news_trend';
    });
  }

  public getPostBySlug(slug: string): BlogPost | undefined {
    this.loadPosts();
    const clean = slug.toLowerCase().replace(/^\/+|\/+$/g, '').replace(/^(guide|blog|how-to|news|noticias|tendencias)\//,'');
    return this.posts.find(p => p.slug === clean || p.toolSlug === clean || p.id === clean);
  }

  public savePost(post: BlogPost): BlogPost {
    this.loadPosts();
    const idx = this.posts.findIndex(p => p.id === post.id);
    const updatedPost: BlogPost = {
      ...post,
      updatedAt: new Date().toISOString().split('T')[0]
    };

    if (idx >= 0) {
      this.posts[idx] = updatedPost;
    } else {
      this.posts.unshift(updatedPost);
    }

    this.saveToStorage();
    return updatedPost;
  }

  public createPost(data: Partial<BlogPost>): BlogPost {
    this.loadPosts();
    const now = new Date().toISOString().split('T')[0];
    const newPost: BlogPost = {
      id: 'blog_' + Math.random().toString(36).substring(2, 9) + '_' + Date.now(),
      slug: data.slug || 'nuevo-articulo-' + Date.now(),
      category: data.category || 'news_trend',
      toolSlug: data.toolSlug || '',
      title: data.title || 'Nuevo Artículo de Blog',
      h1: data.h1 || data.title || 'Título Principal H1',
      excerpt: data.excerpt || 'Resumen introductorio del artículo...',
      content: data.content || '### Introducción\n\nEscribe aquí el contenido completo del artículo con formato...',
      desktopImage: data.desktopImage || '/imagenes para articulos de noticias/Woman_compressing_movie_file_icon_202609051910.jpeg',
      mobileImage: data.mobileImage || data.desktopImage || '/imagenes para articulos de noticias/Woman_compressing_movie_file_icon_202609051910.jpeg',
      imageAlt: data.imageAlt || data.title || 'Imagen del artículo',
      author: data.author || 'Redacción MediaConvert',
      authorRole: data.authorRole || 'Editor de Contenido',
      publishedAt: now,
      updatedAt: now,
      status: data.status || 'published',
      readingTime: data.readingTime || '3 min de lectura',
      tags: data.tags && data.tags.length > 0 ? data.tags : ['Tendencias', 'Google Discover', '2026'],
      seoTitle: data.seoTitle || (data.title ? `${data.title} | MediaConvert` : 'Noticias y Tendencias | MediaConvert'),
      seoMetaDescription: data.seoMetaDescription || data.excerpt || 'Noticias y tendencias en conversión de archivos.',
      seoKeywords: data.seoKeywords || ['tendencias', 'noticias', 'conversor'],
      recommendedToolSlugs: data.recommendedToolSlugs || ['mp4-to-mp3', 'mov-to-mp4', 'jpg-to-png'],
      featuredToolSlugs: data.featuredToolSlugs || ['mp4-to-mp3', 'mov-to-mp4', 'video-to-gif']
    };

    this.posts.unshift(newPost);
    this.saveToStorage();
    return newPost;
  }

  public deletePost(id: string): boolean {
    this.loadPosts();
    const lenBefore = this.posts.length;
    this.posts = this.posts.filter(p => p.id !== id);
    if (this.posts.length !== lenBefore) {
      this.saveToStorage();
      return true;
    }
    return false;
  }

  public resetToDefaults(): void {
    this.posts = [...DEFAULT_POSTS];
    this.saveToStorage();
  }
}

export const blogService = new BlogService();

